head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[wframe > E > onresize]<br/>resizeEvent=true 일때 WFrame 컴포넌트의 크기가 변경되면 70ms 간격으로 발생합니다.",
    "validation" : [     
        "resizeEvent=true 일때 WFrame 컴포넌트의 크기가 변경되면 70ms 간격으로 발생합니다.",
        "resizeInfo 파라미터로 변경된 크기에 대한 정보가 객체로 전달됩니다.",
        "resizeInfo.oldWidth 파라미터로 변경되기 전 WFrame 컴포넌트의 너비(Width)값을 픽셀(px) 단위로 갖습니다.",
        "resizeInfo.oldHeight 파라미터로 변경되기 전 WFrame 컴포넌트의 높이(Height)값을 픽셀(px) 단위로 갖습니다.",
        "resizeInfo.newWidth 파라미터로 변경된 후 WFrame 컴포넌트의 너비(Width)값을 픽셀(px) 단위로 갖습니다.",
        "resizeInfo.newHeight 파라미터로 변경된 후 WFrame 컴포넌트의 높이(Height)값을 픽셀(px) 단위로 갖습니다.",
        "WFrame 컴포넌트에 연결된 WebSquare XML 페이지의 body 태그에 onresize 이벤트를 정의한 경우 WFrame 의 onresize 이벤트 발생 후 body 태그의 onresize 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        src: "/sample/common_link/wframe_resize_1.xml",
        resizeEvent: true,        
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onresize"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:wframe ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="height:300px; background-color:silver;" id=""></w2:wframe>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "wframe",
        strTarget,
        grp_comp
    );
}



scwin.target1_onresize = function (resizeInfo) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onresize=====");   
    wf_body_bottom.getObj("scwin").setReturnValue("resizeInfo : " + resizeInfo);   
    wf_body_bottom.getObj("scwin").setReturnValue("resizeInfo.oldWidth : " + resizeInfo.oldWidth);   
    wf_body_bottom.getObj("scwin").setReturnValue("resizeInfo.oldHeight : " + resizeInfo.oldHeight);   
    wf_body_bottom.getObj("scwin").setReturnValue("resizeInfo.newWidth : " + resizeInfo.newWidth);   
    wf_body_bottom.getObj("scwin").setReturnValue("resizeInfo.newHeight : " + resizeInfo.newHeight);   
}



scwin.btn_setSize_onclick = function (e) {
	target1.setSize(200, 200);
};
